using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
public static class ConnectVisibleSerpentine
{
 public static string Main(){if(Application.isPlaying)throw new Exception("Stop Play");var scene=SceneManager.GetActiveScene();string backup="Assets/Game/Scenes/BeforeVisibleSerpentine.unity";if(File.Exists(backup))throw new Exception("Already patched; inspect before repeating");EditorSceneManager.SaveScene(scene,backup,true);var route=UnityEngine.Object.FindAnyObjectByType<LongRouteStream>();
  var reference=EditorSceneManager.OpenScene("Assets/Game/Scenes/BeforeLongRoute.unity",OpenSceneMode.Additive);
  try{var oldRoots=reference.GetRootGameObjects();foreach(string name in new[]{"Continuous forest ground","Forest - imported dirt road environment"}){var old=oldRoots.First(g=>g.name==name);var current=scene.GetRootGameObjects().First(g=>g.name==name);var map=old.GetComponentsInChildren<MeshFilter>().ToDictionary(f=>f.name);foreach(var f in current.GetComponentsInChildren<MeshFilter>()){if(!map.TryGetValue(f.name,out var original))continue;f.sharedMesh=original.sharedMesh;if(f.TryGetComponent<MeshCollider>(out var mc)&&original.TryGetComponent<MeshCollider>(out var om))mc.sharedMesh=om.sharedMesh;PrefabUtility.RecordPrefabInstancePropertyModifications(f);if(mc!=null)PrefabUtility.RecordPrefabInstancePropertyModifications(mc);}}}
  finally{EditorSceneManager.CloseScene(reference,true);SceneManager.SetActiveScene(scene);}
  if(route.editorPreview!=null)UnityEngine.Object.DestroyImmediate(route.editorPreview);route.entrance=new Vector3(128,3.3f,-39);route.initialForward=new Vector3(.7f,0,.7f);route.openingWaypoints=new[]{route.entrance,new Vector3(145,5,-20),new Vector3(155,9,15),new Vector3(130,15,50),new Vector3(45,24,90),new Vector3(5,30,125),new Vector3(20,36,165),new Vector3(65,43,175),new Vector3(140,53,140),new Vector3(195,62,150),new Vector3(210,69,190),new Vector3(180,76,235),new Vector3(100,88,270),new Vector3(50,99,315),new Vector3(80,108,355),new Vector3(170,122,335),new Vector3(240,135,355),new Vector3(260,145,410)};
  route.ResetPath();route.joinHeights=null;route.EnsurePath();var ground=GameObject.Find("Continuous forest ground");route.joinHeights=new float[route.joinRows*LongRouteStream.AcrossCount];float[] across={-180,-130,-90,-60,-40,-25,-14,-8,-5,0,5,8,14,25,40,60,90,130,180};Physics.SyncTransforms();
  for(int i=0;i<route.joinRows;i++)for(int j=0;j<across.Length;j++){var p=route.Point(i*10)+Vector3.Cross(Vector3.up,route.Tangent(i*10)).normalized*across[j];var hits=Physics.RaycastAll(new Vector3(p.x,200,p.z),Vector3.down,400,~0,QueryTriggerInteraction.Ignore).Where(h=>h.transform.IsChildOf(ground.transform)).OrderBy(h=>h.distance).ToArray();route.joinHeights[i*across.Length+j]=hits.Length>0?hits[0].point.y:route.Point(i*10).y;}
  string folder="Assets/Game/Generated/VisibleSerpentine";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var centers=Enumerable.Range(0,81).Select(i=>route.Point(i*10)).ToArray();int changed=0;
  foreach(var f in ground.GetComponentsInChildren<MeshFilter>()){var bounds=f.GetComponent<Renderer>().bounds;if(!centers.Any(p=>bounds.SqrDistance(p)<35*35))continue;var mesh=UnityEngine.Object.Instantiate(f.sharedMesh);var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++){var p=f.transform.TransformPoint(vertices[i]);double sBest=-1;float best=20*20,cross=0;for(int j=0;j<80;j++){var d=centers[j+1]-centers[j];d.y=0;var q=p-centers[j];q.y=0;float t=Mathf.Clamp01(Vector3.Dot(q,d)/d.sqrMagnitude);var delta=q-d*t;if(delta.sqrMagnitude<best){best=delta.sqrMagnitude;sBest=(j+t)*10;cross=Vector3.Dot(delta,Vector3.Cross(Vector3.up,d.normalized));}}if(sBest<0)continue;float blend=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(7,20,Mathf.Abs(cross)));p.y=Mathf.Lerp(p.y,route.CrossHeight(sBest,cross)-.18f,blend);vertices[i]=f.transform.InverseTransformPoint(p);}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/Join "+f.name+".asset");f.sharedMesh=mesh;f.GetComponent<MeshCollider>().sharedMesh=mesh;changed++;}
  route.editorPreview=new GameObject("Visible mountain serpentine preview");route.editorPreview.transform.SetParent(route.transform,false);for(int i=0;i<8;i++){var chunk=route.BuildChunk(i);AssetDatabase.CreateAsset(chunk.GetComponent<MeshFilter>().sharedMesh,folder+"/Road "+i+".asset");chunk.transform.SetParent(route.editorPreview.transform,true);}
  var tiles=route.DesiredTerrain(2);foreach(var key in tiles){var tile=route.BuildTerrainTile(key);AssetDatabase.CreateAsset(tile.GetComponent<MeshFilter>().sharedMesh,folder+"/Ground "+key.x+" "+key.y+".asset");tile.transform.SetParent(route.editorPreview.transform,true);}
  var sign=GameObject.Find("Route extension entrance sign");if(sign!=null){sign.transform.position=route.entrance+new Vector3(-6,3,0);sign.transform.rotation=Quaternion.LookRotation(-route.initialForward);}
  EditorUtility.SetDirty(route);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return "Connected visible road end at "+route.entrance+" to 18-point climbing serpentine; rebuilt 1.6km preview, "+tiles.Count+" continuous terrain tiles; old west-end alteration restored; join chunks="+changed;
 }
}
